using System.Text;

namespace BraunauMobil.VeloBasar.Tests.BusinessLogic.QrImportServiceTests;

/// <summary>
/// Test-side encoder for the DataTransfer QR payload (schema version 3), written independently of
/// <see cref="BraunauMobil.VeloBasar.BusinessLogic.QrImportService"/> so the tests don't just mirror its decoder.
/// The constants below were generated by a separate reference implementation of the contract and are identical to
/// the examples in the DataTransfer README.
/// </summary>
internal static class QrPayload
{
    // Anna|Muster|Hauptplatz 1|Braunau am Inn|5280|AUT|anna.muster@example.com|+43 664 1234567|AT611904300234573201||true
    public const string Seller = "VB3S85N6SO899LQN6T35E84KGOBLE1Q70R31EHT20C8989P62TBEC5QI0OBD414MSRG96KP3GC0985AL82B1DPN62BJDELPN8PBI81INGOBDE1M6ABJ3DTMGIAPK6CG3CDHK40OJ4CPK6KR3E2A1AGR32C9P60Q36C1G68PJ8D9N6CP30C8915Q74TB5ULFG";

    // Anna|Muster|Hauptplatz 1|Braunau am Inn|5280|AUT||+43 664 1234567|||false
    public const string SellerWithoutOptionalFields = "VB3S85N6SO899LQN6T35E84KGOBLE1Q70R31EHT20C8989P62TBEC5QI0OBD414MSRG96KP3GC0985AL82895CQ3681M6OQ20C9I6CQ3ADHN144GIPJ1DHPMBVDE";

    // Jürgen|Müller|Straße 1|Braunau am Inn|5280|AUT||+43 664 1234567||C:\Temp ß€|false
    public const string SellerWithNonAscii = "VB3S9B1ROSJ7CLN0IJE3NHM6OPBI159N8SJ1OEFMA81H15174OBLDPGNA831DKG4IRJE14QJ4E1G150LAL0914LJ8CP06OR3881H68PJ8D9M6S4GIGPQBHA6ARBG431PVOK2LG4MCOBCEDIJ9TO";

    // KTM|Mountainbike|28 Zoll, guter Zustand|Schwarz/Rot|ABC123|28"|249.5|false
    public const string Product = "VB3P9DA4Q2ADDTQMST31D5N64QBBCK4J4E10B9NMOR1C41JNAT35E8G5KTBJEHGMSP09ADHMGTR1E9T2UKJFEG4K2GI364P3629I70H0ICHK74N3A2B6C5M76PAFPK";

    // KTM|Mountainbike|Test||||100|true
    public const string ProductWithoutOptionalFields = "VB3P9DA4Q2ADDTQMST31D5N64QBBCK4L8PBJEG4GI28964O302BKE9QMB0K6";

    // KTM|Mountainbike|Schöner Zustand, Größe M|Grün||||100|false
    public const string ProductWithNonAscii = "VB3P9DA4Q2ADDTQMST31D5N64QBBCK4L6OR8OER6SPBI41D7ASRKC5N68B108TPC7DM3JTII0J898TPC7F3E144GIC9G604MCOBCEDIK3K0";

    // KTM|Mountainbike (valid CRC, but too few fields)
    public const string ProductWithTooFewFields = "VB3P9DA4Q2ADDTQMST31D5N64QBBCNU86";

    private const string Alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUV";

    public static string Encode(int schemaVersion, char kind, params string[] fields)
        => EncodeBytes(schemaVersion, kind, Encoding.UTF8.GetBytes(string.Join('\t', fields)));

    public static string EncodeBytes(int schemaVersion, char kind, byte[] data)
    {
        ArgumentNullException.ThrowIfNull(data);

        int crc = 0xFFFF;
        foreach (byte b in data)
        {
            crc ^= b << 8;
            for (int i = 0; i < 8; i++)
            {
                crc = (crc & 0x8000) != 0 ? ((crc << 1) ^ 0x1021) & 0xFFFF : (crc << 1) & 0xFFFF;
            }
        }
        byte[] withCrc = [.. data, (byte)(crc >> 8), (byte)(crc & 0xFF)];

        StringBuilder body = new();
        int buffer = 0;
        int bits = 0;
        foreach (byte b in withCrc)
        {
            buffer = (buffer << 8) | b;
            bits += 8;
            while (bits >= 5)
            {
                body.Append(Alphabet[(buffer >> (bits - 5)) & 31]);
                bits -= 5;
            }
            buffer &= (1 << bits) - 1;
        }
        if (bits > 0)
        {
            body.Append(Alphabet[(buffer << (5 - bits)) & 31]);
        }

        return $"VB{schemaVersion}{kind}{body}";
    }

    /// <summary>Simulates a scanner that dropped one character while typing.</summary>
    public static string DropCharacter(string payload, int index)
    {
        ArgumentNullException.ThrowIfNull(payload);
        return payload.Remove(index, 1);
    }

    /// <summary>Simulates a scanner that typed one wrong (but still valid base32hex) character.</summary>
    public static string ReplaceCharacter(string payload, int index)
    {
        ArgumentNullException.ThrowIfNull(payload);
        char replacement = payload[index] == '1' ? '2' : '1';
        return string.Concat(payload.AsSpan(0, index), replacement.ToString(), payload.AsSpan(index + 1));
    }
}
